<?php
require dirname(__DIR__,2).'/src/bootstrap.php';
sessionStart();header('Cache-Control: no-store');$error='';$notice='';
$kinds=['projects'=>'Projects','services'=>'Services','insights'=>'Insights','testimonials'=>'Testimonials','team'=>'Team'];
try {
if ($_SERVER['REQUEST_METHOD']==='POST') {
    csrf();$action=$_POST['action']??'';
    if ($action==='login') {
        if(!rateLimit('login:'.($_SERVER['REMOTE_ADDR']??''),8,900)) { $error='Too many login attempts. Try again in 15 minutes.'; }
        elseif(hash_equals(strtolower(trim((string)config()['admin_email'])),strtolower(trim((string)($_POST['email']??'')))) && password_verify((string)($_POST['password']??''),(string)config()['admin_password_hash'])) { session_regenerate_id(true);$_SESSION['admin']=true;$_SESSION['csrf']=bin2hex(random_bytes(32));header('Location: /admin/');exit; }
        else $error='The email or password is incorrect.';
    } elseif(!empty($_SESSION['admin'])) {
        if($action==='logout'){$_SESSION=[];session_destroy();header('Location: /admin/');exit;}
        if($action==='save') {
            $kind=(string)($_POST['kind']??'');if(!isset($kinds[$kind])) throw new RuntimeException('Invalid section.');
            $title=trim((string)($_POST['title']??''));$slug=trim((string)($_POST['slug']??''));
            if(!$title||strlen($title)>240||!preg_match('/^[a-z0-9]+(?:-[a-z0-9]+)*$/',$slug)) throw new RuntimeException('Enter a title and a URL slug using lowercase letters, numbers and hyphens.');
            $metadata=[];foreach(['industry','client','problem','solution','technologies','images','featuredImage','completionDate','seoTitle','seoDescription','author'] as $key) $metadata[$key]=trim((string)($_POST[$key]??''));
            $metadata['featured']=isset($_POST['featured']);
            $values=[$kind,$title,$slug,substr((string)($_POST['category']??''),0,80),(string)($_POST['summary']??''),(string)($_POST['content']??''),json_encode($metadata),isset($_POST['published'])?1:0,gmdate('c')];
            $id=(int)($_POST['id']??0);
            if($id){$values[]=$id;db()->prepare('UPDATE entries SET kind=?,title=?,slug=?,category=?,summary=?,content=?,metadata=?,published=?,updated_at=? WHERE id=?')->execute($values);}
            else {$values[]=gmdate('c');db()->prepare('INSERT INTO entries (kind,title,slug,category,summary,content,metadata,published,updated_at,created_at) VALUES (?,?,?,?,?,?,?,?,?,?)')->execute($values);}
            $notice='Content saved.';
        }
        if($action==='unpublish'){db()->prepare('UPDATE entries SET published=0,updated_at=? WHERE id=?')->execute([gmdate('c'),(int)$_POST['id']]);$notice='Entry unpublished. The content is retained in the archive.';}
        if($action==='message'){ $status=in_array($_POST['status']??'', ['New','In progress','Closed'],true)?$_POST['status']:'New';db()->prepare('UPDATE inquiries SET status=? WHERE id=?')->execute([$status,(int)$_POST['id']]);$notice='Inquiry updated.'; }
        if($action==='site-request'){ $status=in_array($_POST['status']??'', ['New','Contacted','Quoted','In progress','Won','Closed'],true)?$_POST['status']:'New';db()->prepare('UPDATE site_requests SET status=? WHERE id=?')->execute([$status,(int)$_POST['id']]);$notice='Website request updated.'; }
        if($action==='review-status'){ $status=in_array($_POST['status']??'', ['Pending','Approved','Rejected'],true)?$_POST['status']:'Pending';db()->prepare('UPDATE reviews SET status=?,updated_at=? WHERE id=?')->execute([$status,gmdate('c'),(int)$_POST['id']]);$notice=$status==='Approved'?'Review approved and published.':'Review status updated.'; }
        if($action==='partner-save'){
            $name=trim((string)($_POST['name']??''));$url=trim((string)($_POST['url']??''));if(!$name||strlen($name)>180||!filter_var($url,FILTER_VALIDATE_URL))throw new RuntimeException('Enter a partner name and a complete website URL.');
            $values=[$name,$url,substr(trim((string)($_POST['description']??'')),0,2000),substr(trim((string)($_POST['logo_url']??'')),0,500),isset($_POST['featured'])?1:0,isset($_POST['visible'])?1:0,(int)($_POST['sort_order']??0),gmdate('c')];$id=(int)($_POST['id']??0);
            if($id){$values[]=$id;db()->prepare('UPDATE partners SET name=?,url=?,description=?,logo_url=?,featured=?,visible=?,sort_order=?,updated_at=? WHERE id=?')->execute($values);}else{$values[]=gmdate('c');db()->prepare('INSERT INTO partners(name,url,description,logo_url,featured,visible,sort_order,updated_at,created_at) VALUES(?,?,?,?,?,?,?,?,?)')->execute($values);}$notice='Partner saved.';
        }
        if($action==='partner-toggle'){db()->prepare('UPDATE partners SET visible=CASE WHEN visible=1 THEN 0 ELSE 1 END,updated_at=? WHERE id=?')->execute([gmdate('c'),(int)$_POST['id']]);$notice='Partner visibility updated.';}
        if($action==='settings') {
            foreach(['heroHeadline','heroDescription','email','phone','location','projectsDelivered','technologies','disciplines','clients'] as $key){$v=trim((string)($_POST[$key]??''));if(strlen($v)>2000)throw new RuntimeException('Setting too long.');db()->prepare('DELETE FROM settings WHERE name=?')->execute([$key]);db()->prepare('INSERT INTO settings(name,value) VALUES (?,?)')->execute([$key,$v]);}
            $notice='Settings saved.';
        }
    } else { http_response_code(403);$error='Please sign in.'; }
}
}catch(Throwable $e){error_log('Vitaw admin: '.$e->getMessage());$error=$e instanceof PDOException?'The change could not be saved. Check the slug is unique and the database is configured.':$e->getMessage();}
$section=(string)($_GET['section']??'dashboard');
function token(): void {echo '<input type="hidden" name="csrf" value="'.esc($_SESSION['csrf']).'">';}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Vitaw | Administration</title><link rel="stylesheet" href="/admin/admin.css"></head><body><header><a href="/">VITAW <small>ADMINISTRATION</small></a><?php if(!empty($_SESSION['admin'])):?><form method="post"><?php token();?><button name="action" value="logout">Sign out</button></form><?php endif;?></header>
<?php if(empty($_SESSION['admin'])): ?><main class="login"><span class="eyebrow">SECURE ADMIN PORTAL</span><h1>Welcome back.</h1><p>Sign in to manage the Vitaw website.</p><div class="login-status" aria-live="polite"><?php if($error):?><p class="alert" role="alert"><?=esc($error)?></p><?php else:?><p class="form-help">Use the administrator email and the password created on the secure reset page.</p><?php endif;?></div><form method="post" action="/admin/" id="login-form"><?php token();?><input type="hidden" name="action" value="login"><label>Email<input type="email" name="email" required autocomplete="username" value="<?=esc($_POST['email']??'')?>"></label><label>Password<input type="password" name="password" required autocomplete="current-password"></label><button type="submit" id="login-button">Sign in →</button></form><p><a href="/">← Back to website</a></p></main><script>document.getElementById('login-form').addEventListener('submit',function(){const b=document.getElementById('login-button');b.textContent='Checking credentials…';b.setAttribute('aria-busy','true')});</script>
<?php else:?><?php $adminSections=['dashboard'=>'Dashboard']+$kinds+['site-requests'=>'Website requests','reviews'=>'Review approvals','partners'=>'Partners','messages'=>'Messages','media'=>'Media','settings'=>'Site settings'];?><div class="layout"><aside><?php foreach($adminSections as $key=>$label):?><a class="<?=$section===$key?'active':''?>" href="?section=<?=esc($key)?>"><?=esc($label)?></a><?php endforeach;?></aside><main><span class="eyebrow">VITAW / CONTENT MANAGEMENT</span><h1><?=esc($adminSections[$section]??'Dashboard')?></h1><?php if($error):?><p class="alert" role="alert"><?=esc($error)?></p><?php endif;?><?php if($notice):?><p class="notice" role="status"><?=esc($notice)?></p><?php endif;?>
<?php if(isset($kinds[$section])):
$edit=null;if(isset($_GET['edit'])){$s=db()->prepare('SELECT * FROM entries WHERE id=? AND kind=?');$s->execute([(int)$_GET['edit'],$section]);$edit=$s->fetch()?:null;}$meta=$edit?json_decode($edit['metadata'],true):[];
?><h2><?=$edit?'Edit entry':'Create entry'?></h2><form method="post"><?php token();?><input type="hidden" name="action" value="save"><input type="hidden" name="kind" value="<?=esc($section)?>"><input type="hidden" name="id" value="<?=esc($edit['id']??0)?>"><div class="grid"><?php foreach(['title'=>'Title','slug'=>'URL slug','category'=>'Category','industry'=>'Industry','client'=>'Client (only with permission)','completionDate'=>'Completion date','author'=>'Author','featuredImage'=>'Featured image URL','images'=>'Additional image URLs (one per line)','technologies'=>'Technologies (comma separated)','seoTitle'=>'SEO title','seoDescription'=>'SEO description'] as $key=>$label):?><label><?=esc($label)?><input name="<?=esc($key)?>" value="<?=esc($edit[$key]??$meta[$key]??'')?>" <?=in_array($key,['title','slug'])?'required':''?>></label><?php endforeach;?></div><?php foreach(['summary'=>'Short description','problem'=>'Problem','solution'=>'Solution','content'=>'Full description / article (plain text; blank lines create paragraphs)'] as $key=>$label):?><label><?=esc($label)?><textarea rows="5" name="<?=esc($key)?>"><?=esc($edit[$key]??$meta[$key]??'')?></textarea></label><?php endforeach;?><label class="check"><input type="checkbox" name="featured" <?=!empty($meta['featured'])?'checked':''?>> Featured</label><label class="check"><input type="checkbox" name="published" <?=!empty($edit['published'])?'checked':''?>> Publish on website</label><button>Save entry</button></form><h2>Content archive</h2><?php $s=db()->prepare('SELECT * FROM entries WHERE kind=? ORDER BY updated_at DESC');$s->execute([$section]);foreach($s as $row):?><div class="record"><a href="?section=<?=esc($section)?>&edit=<?=$row['id']?>"><?=esc($row['title'])?></a><span><?=$row['published']?'Published':'Draft'?></span><form method="post"><?php token();?><input type="hidden" name="id" value="<?=$row['id']?>"><button name="action" value="unpublish">Unpublish</button></form></div><?php endforeach;?>
<?php elseif($section==='messages'): foreach(db()->query('SELECT * FROM inquiries ORDER BY created_at DESC') as $row):?><article class="message"><h2><?=esc($row['name'])?> · <?=esc($row['project_type'])?></h2><p><?=esc($row['created_at'])?> / <?=esc($row['company'])?></p><p><?=esc($row['email'])?> / <?=esc($row['phone'])?> / <?=esc($row['budget'])?></p><p class="preserve"><?=esc($row['description'])?></p><?php if($row['attachment']):?><a href="/admin/download.php?id=<?=$row['id']?>">Download supporting document</a><?php endif;?><form method="post"><?php token();?><input type="hidden" name="id" value="<?=$row['id']?>"><input type="hidden" name="action" value="message"><label>Status<select name="status"><?php foreach(['New','In progress','Closed'] as $v):?><option <?=$row['status']===$v?'selected':''?>><?=esc($v)?></option><?php endforeach;?></select></label><button>Update status</button></form></article><?php endforeach;?>
<?php elseif($section==='site-requests'): $requests=db()->query('SELECT * FROM site_requests ORDER BY created_at DESC')->fetchAll();if(!$requests):?><p class="empty-admin">No website requests yet. New public submissions will appear here.</p><?php endif;foreach($requests as $row):?><article class="message"><span class="status-pill"><?=esc($row['status'])?></span><h2><?=esc($row['name'])?> · <?=esc($row['website_type']?:'Website')?></h2><p><?=esc($row['created_at'])?> / <?=esc($row['company'])?></p><p><a href="mailto:<?=esc($row['email'])?>"><?=esc($row['email'])?></a> / <?=esc($row['phone'])?> / <?=esc($row['budget'])?> / <?=esc($row['timeline'])?></p><p class="preserve"><?=esc($row['features'])?></p><?php if($row['reference_url']):?><p><a href="<?=esc($row['reference_url'])?>" target="_blank" rel="noopener">Open reference website ↗</a></p><?php endif;?><form method="post"><?php token();?><input type="hidden" name="id" value="<?=$row['id']?>"><input type="hidden" name="action" value="site-request"><label>Status<select name="status"><?php foreach(['New','Contacted','Quoted','In progress','Won','Closed'] as $v):?><option <?=$row['status']===$v?'selected':''?>><?=esc($v)?></option><?php endforeach;?></select></label><button>Update request</button></form></article><?php endforeach;?>
<?php elseif($section==='reviews'): $reviews=db()->query('SELECT * FROM reviews ORDER BY created_at DESC')->fetchAll();if(!$reviews):?><p class="empty-admin">No submitted reviews yet.</p><?php endif;foreach($reviews as $row):?><article class="message"><span class="status-pill"><?=esc($row['status'])?></span><h2><?=str_repeat('★',(int)$row['rating'])?> · <?=esc($row['name'])?></h2><p><?=esc($row['reviewer_role'])?><?=($row['reviewer_role']&&$row['company'])?' at ':''?><?=esc($row['company'])?></p><p class="preserve"><?=esc($row['review'])?></p><form method="post" class="inline-actions"><?php token();?><input type="hidden" name="id" value="<?=$row['id']?>"><input type="hidden" name="action" value="review-status"><button name="status" value="Approved">Approve & publish</button><button class="secondary" name="status" value="Pending">Keep pending</button><button class="danger" name="status" value="Rejected">Reject</button></form></article><?php endforeach;?>
<?php elseif($section==='partners'): $partner=null;if(isset($_GET['edit'])){$s=db()->prepare('SELECT * FROM partners WHERE id=?');$s->execute([(int)$_GET['edit']]);$partner=$s->fetch()?:null;}?><h2><?=$partner?'Edit partner':'Add partner'?></h2><form method="post"><?php token();?><input type="hidden" name="action" value="partner-save"><input type="hidden" name="id" value="<?=esc($partner['id']??0)?>"><div class="grid"><label>Partner name<input name="name" required maxlength="180" value="<?=esc($partner['name']??'')?>"></label><label>Website URL<input name="url" type="url" required placeholder="https://example.com/" value="<?=esc($partner['url']??'')?>"></label><label>Logo URL (optional)<input name="logo_url" placeholder="/media/partner-logo.webp" value="<?=esc($partner['logo_url']??'')?>"></label><label>Display priority<input name="sort_order" type="number" value="<?=esc($partner['sort_order']??0)?>"></label></div><label>Description<textarea name="description" rows="4" maxlength="2000"><?=esc($partner['description']??'')?></textarea></label><label class="check"><input type="checkbox" name="featured" <?=!empty($partner['featured'])?'checked':''?>> Featured partner</label><label class="check"><input type="checkbox" name="visible" <?=!empty($partner['visible'])?'checked':''?>> Show on public website</label><button>Save partner</button></form><h2>Partner directory</h2><?php foreach(db()->query('SELECT * FROM partners ORDER BY featured DESC,sort_order DESC,name') as $row):?><div class="record"><div><strong><?=esc($row['name'])?></strong><br><a href="<?=esc($row['url'])?>" target="_blank" rel="noopener"><?=esc($row['url'])?></a></div><span><?=$row['visible']?'Visible':'Hidden'?><?=$row['featured']?' · Featured':''?></span><div class="inline-actions"><a class="admin-button" href="?section=partners&edit=<?=$row['id']?>">Edit</a><form method="post"><?php token();?><input type="hidden" name="id" value="<?=$row['id']?>"><button name="action" value="partner-toggle"><?=$row['visible']?'Hide from site':'Show on site'?></button></form></div></div><?php endforeach;?>
<?php elseif($section==='settings'): $settings=[];foreach(db()->query('SELECT * FROM settings') as $r)$settings[$r['name']]=$r['value'];?><form method="post"><?php token();?><input type="hidden" name="action" value="settings"><?php foreach(['heroHeadline'=>'Homepage headline','heroDescription'=>'Homepage introduction','email'=>'Contact email','phone'=>'Contact phone (international format)','location'=>'Location','projectsDelivered'=>'Projects delivered (verified figures only)','technologies'=>'Technologies (verified figure)','disciplines'=>'Engineering disciplines (verified figure)','clients'=>'Clients (verified figure)'] as $key=>$label):?><label><?=esc($label)?><input name="<?=esc($key)?>" value="<?=esc($settings[$key]??'')?>"></label><?php endforeach;?><button>Save settings</button></form>
<?php elseif($section==='media'):?><p>Upload optimized project images through Hostinger File Manager into <code>public_html/media/</code>, then use their <code>/media/filename.webp</code> URLs in project entries. Inquiry documents stay in private storage and are accessible only through Messages.</p>
<?php else:?><div class="stats"><?php foreach(['projects'=>'Project entries','insights'=>'Articles'] as $kind=>$label):$s=db()->prepare('SELECT COUNT(*) FROM entries WHERE kind=?');$s->execute([$kind]);?><article><strong><?=$s->fetchColumn()?></strong><span><?=esc($label)?></span></article><?php endforeach;?><article><strong><?=db()->query('SELECT COUNT(*) FROM inquiries')->fetchColumn()?></strong><span>Inquiries</span></article></div><h2>Publishing workflow</h2><p>Create content, review the details and enable “Publish on website” when ready. Only published entries appear publicly. Leave company statistics empty until verified.</p><?php endif;?></main></div><?php endif;?></body></html>
